TArray<FString> BuildHelpLines(const FString& Query)
{
 TArray<FString> Lines; const FString Q=Query.TrimStartAndEnd();
 if(Q.IsEmpty()){Lines.Add(TEXT("HELP: empty query. Use /help [ID or name]."));return Lines;}
 const auto& V=Entries(); TArray<int32> Hits;
 for(int32 I=0;I<V.Num();++I) if(V[I].Id.Equals(Q,ESearchCase::IgnoreCase)||V[I].Name.Equals(Q,ESearchCase::IgnoreCase)) Hits.Add(I);
 if(Hits.Num()==0) for(int32 I=0;I<V.Num();++I) if(V[I].Id.Contains(Q,ESearchCase::IgnoreCase)||V[I].Name.Contains(Q,ESearchCase::IgnoreCase)) Hits.Add(I);
 if(Hits.Num()==0){Lines.Add(FString::Printf(TEXT("HELP: no item/card/job-artifact/pet match for '%s'."),*Q));return Lines;}
 if(Hits.Num()>8){Lines.Add(FString::Printf(TEXT("HELP: %d matches; showing first 8:"),Hits.Num()));for(int32 I=0;I<8;++I)Lines.Add(FString::Printf(TEXT("%s | %s"),*V[Hits[I]].Id,*V[Hits[I]].Name));return Lines;}
 for(int32 I:Hits){const auto& E=V[I];Lines.Add(FString::Printf(TEXT("%s | %s | %s"),*E.Id,*E.Name,*E.Type));Lines.Add(FString::Printf(TEXT("  %s"),*E.Details));Lines.Add(FString::Printf(TEXT("  Find: %s"),*E.Source));Lines.Add(FString::Printf(TEXT("  When: %s"),*E.When));}
 return Lines;
}
